import{_ as s,o as t,a as n,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"数据搬运","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/data_move"},{"text":"Copy（UB -> UB连续数据搬运）","link":"/api/SIMD-API/basic_api/memory_vector_compute/data_move/Copy_UBToUB_continuous"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/Copy_UBToUB_continuous.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/data_move/Copy_UBToUB_continuous.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),p={name:"api/SIMD-API/basic_api/memory_vector_compute/data_move/Copy_UBToUB_continuous.md"};function i(e,a,c,o,d,r){return t(),n("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>Copy（UBToUB连续数据搬运）<span id="ZH-CN_TOPIC_0000002575088175"></span></h1><h2 id="产品支持情况">产品支持情况<span id="zh-cn_topic_0000002567699435_section796754519912"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：不支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="zh-cn_topic_0000002567699435_section106841136114319"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_data_copy_intf.h&quot;</code>。</p><p>支持Unified Buffer（UB）内部的连续数据搬运，数据搬运时格式和内容保持不变。</p><p>具体支持的数据通路为（以<a href="../../aux_data_structures/TPosition.html">逻辑位置TPosition</a>表示）：</p><ul><li>UB -&gt; UB <ul><li>VECIN -&gt; VECCALC</li><li>VECIN -&gt; VECOUT</li><li>VECCALC -&gt; VECIN</li><li>VECCALC -&gt; VECOUT</li><li>VECOUT -&gt; VECIN</li><li>VECOUT -&gt; VECCALC</li></ul></li></ul><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000002567699435_section82039854412"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">isSetMask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">count</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="zh-cn_topic_0000002567699435_section16128134420472"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源操作数或者目的操作数的数据类型。支持的数据类型请参考<a href="#zh-cn_topic_0000002567699435_section42191353048181">数据类型</a>。</td></tr><tr><td>isSetMask</td><td>参数不生效，保持默认值true即可。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。<br>类型为<a href="../../data_structures/LocalTensor/LocalTensor_intro.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。起始地址需要保证32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。<br>类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。起始地址需要保证32字节对齐。<br>源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>count</td><td>输入</td><td>参与搬运的元素个数。</td></tr></tbody></table><h2 id="数据类型">数据类型<span id="zh-cn_topic_0000002567699435_section42191353048181"></span><a class="header-anchor" href="#数据类型">​</a></h2><p>源操作数和目的操作数支持的数据类型保持一致。</p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、uint8_t、fp4x2_e2m1_t、fp4x2_e1m2_t、hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、uint64_t。</p></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="zh-cn_topic_0000002567699435_section2045914466492"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>位于UB的地址必须32字节对齐。</li><li>操作数地址重叠约束请参考<a href="../../../general_description_and_constraints.html#%E9%80%9A%E7%94%A8%E5%9C%B0%E5%9D%80%E9%87%8D%E5%8F%A0%E7%BA%A6%E6%9D%9F">通用地址重叠约束</a>。</li><li>isSetMask参数不生效，保持默认值true即可。</li></ul><h2 id="调用示例">调用示例<span id="zh-cn_topic_0000002567699435_section088124295117"></span><a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">Copy</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">srcLocal</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const u=s(p,[["render",i]]);export{h as __pageData,u as default};
